package dev.linkgate.agent;

import dev.linkgate.contracts.ManifestContract;
import dev.linkgate.contracts.WireJson;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.UUID;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class AgentRegistryTest {
    private Path directory;private AgentRegistry.Database database;private AgentRegistry registry;private long now=1000000;
    private static final String PEER="3333333333333333333333333333333333333333333333333333333333333333",DEVICE="1111111111111111111111111111111111111111111111111111111111111111",ROOT="2222222222222222222222222222222222222222222222222222222222222222";
    @Before public void setup()throws Exception {
        Path parent=Path.of("build/registry-tests").toAbsolutePath().normalize();Files.createDirectories(parent);directory=parent.resolve(UUID.randomUUID().toString());Files.createDirectory(directory);
        database=()->{try{return new Jdbc(DriverManager.getConnection("jdbc:sqlite:"+directory.resolve("state.db")));}catch(Exception e){throw new IllegalStateException();}};
        registry=new AgentRegistry(database,()->now);registry.bindIdentity(DEVICE,ROOT);
    }
    @After public void cleanup()throws Exception {
        Path parent=Path.of("build/registry-tests").toAbsolutePath().normalize();if(directory==null||!directory.startsWith(parent)||directory.equals(parent))throw new IllegalStateException("Unsafe cleanup.");
        try(var paths=Files.walk(directory)){for(Path path:(Iterable<Path>)paths.sorted(java.util.Comparator.reverseOrder())::iterator)Files.delete(path);}
    }
    private String register(String caller,String label){return text(registry.register(caller,"verified package provenance",UUID.randomUUID(),ManifestContract.parse(manifest(label))),"applicationRef");}
    private static byte[] manifest(String label){return ("{\"manifestVersion\":1,\"applicationId\":\"org.example.mobile-client\",\"displayName\":\""+label+"\",\"exports\":[],\"imports\":[{\"alias\":\"files\",\"protocol\":\"tcp\",\"endpointMode\":\"brokered\",\"connectionPolicy\":{\"mode\":\"direct-only\",\"allowRelay\":false}}]}").getBytes(StandardCharsets.UTF_8);}
    private String approveFixture(){String app=register("caller","Client");registry.decide(registry.review(app),"approve",UUID.randomUUID());registry.trustPeer(PEER,"validated public fixture certificate","127.0.0.1",17443,0,UUID.randomUUID());return app;}
    private String request(String caller,String app){return text(registry.requestAccess(caller,UUID.randomUUID(),app,"files",PEER,"org.example.publisher","files","user request"),"grantRequestId");}
    private AgentRegistry.Scope scope(String app){return registry.authorize("caller",app,"files",PEER,"org.example.publisher","files");}
    private static String text(String json,String field){return WireJson.text(WireJson.read(json.getBytes(StandardCharsets.UTF_8),65536).get(field),128);}
    private static void denied(String code,Runnable action){try{action.run();fail("Request accepted.");}catch(AgentRegistry.Failure e){assertEquals(code,e.code);}}
    @Test public void appApprovalAndPeerTrustDoNotImplicitlyGrantAccess(){String app=approveFixture();denied("AUTH_REQUIRED",()->scope(app));String request=request("caller",app);denied("AUTH_REQUIRED",()->scope(app));registry.approveAccess(request,0,UUID.randomUUID());assertEquals("127.0.0.1",scope(app).host);assertEquals(1,scope(app).grantRevision);}
    @Test public void callersAndReinstallGenerationsCannotInheritLocalAccess(){String app=approveFixture();registry.approveAccess(request("caller",app),0,UUID.randomUUID());denied("AUTH_REQUIRED",()->registry.authorize("new-install",app,"files",PEER,"org.example.publisher","files"));String reinstalled=register("new-install","Reinstalled");registry.decide(registry.review(reinstalled),"approve",UUID.randomUUID());denied("AUTH_REQUIRED",()->registry.authorize("new-install",reinstalled,"files",PEER,"org.example.publisher","files"));}
    @Test public void deniedPendingUpdatePreservesApprovedAuthority(){String app=approveFixture();registry.approveAccess(request("caller",app),0,UUID.randomUUID());AgentRegistry.Scope before=scope(app);register("caller","New unapproved label");registry.decide(registry.review(app),"deny",UUID.randomUUID());assertEquals(before.json(),scope(app).json());assertTrue(registry.currentScopes(Arrays.asList(before))[0]);}
    @Test public void staleReviewAndStaleRequestCannotRestoreAccess(){String app=approveFixture();AgentRegistry.Review selected=registry.review(app);String request=request("caller",app);register("caller","Changed");denied("REVIEW_STALE",()->registry.decide(selected,"approve",UUID.randomUUID()));registry.decide(registry.review(app),"approve",UUID.randomUUID());denied("REVIEW_STALE",()->registry.approveAccess(request,0,UUID.randomUUID()));}
    @Test public void peerRevocationDisablesGrantsAndRetrustDoesNotReviveThem(){String app=approveFixture();String request=request("caller",app);registry.approveAccess(request,0,UUID.randomUUID());AgentRegistry.Scope before=scope(app);registry.revokePeer(PEER,1,UUID.randomUUID());assertFalse(registry.currentScopes(Arrays.asList(before))[0]);registry.trustPeer(PEER,"validated public fixture certificate","127.0.0.1",17443,2,UUID.randomUUID());denied("AUTH_REQUIRED",()->scope(app));}
    @Test public void oldApprovalOutcomeDoesNotReactivateRevokedGrant(){String app=approveFixture(),request=request("caller",app);UUID operation=UUID.randomUUID();String original=registry.approveAccess(request,0,operation);registry.revokeAccess(request,1,UUID.randomUUID());assertEquals(original,registry.approveAccess(request,0,operation));denied("AUTH_REQUIRED",()->scope(app));}
    @Test public void opensAreDurableCallerBoundAndNeverRecreatedAfterRestart(){String app=approveFixture();registry.approveAccess(request("caller",app),0,UUID.randomUUID());UUID operation=UUID.randomUUID(),boot=UUID.randomUUID();AgentRegistry.Open opened=registry.beginOpen("caller",operation,app,"files",PEER,"org.example.publisher","files",boot);assertTrue(opened.created);assertFalse(registry.beginOpen("caller",operation,app,"files",PEER,"org.example.publisher","files",boot).created);denied("OPERATION_CONFLICT",()->registry.beginOpen("caller",operation,app,"files",PEER,"org.example.publisher","other",boot));denied("OPERATION_UNKNOWN",()->registry.openStatus("other",operation));registry=new AgentRegistry(database,()->now);UUID next=UUID.randomUUID();registry.recoverOpens(next);AgentRegistry.Open recovered=registry.beginOpen("caller",operation,app,"files",PEER,"org.example.publisher","files",next);assertFalse(recovered.created);assertEquals(opened.reference,recovered.reference);assertEquals("closed",recovered.state);assertEquals("AGENT_RESTARTED",recovered.error);}
    @Test public void clockRollbackAndIdentityReplacementFailClosed(){String app=approveFixture();registry.approveAccess(request("caller",app),0,UUID.randomUUID());now=1;denied("CLOCK_UNTRUSTED",()->scope(app));denied("IDENTITY_CHANGED",()->registry.bindIdentity(PEER,ROOT));}
    @Test public void logicalRevocationSlotsSurviveAFullOperationJournal(){registry=new AgentRegistry(database,()->now,12,16);String app=approveFixture(),request=request("caller",app);registry.approveAccess(request,0,UUID.randomUUID());int accepted=0;while(true){try{register("caller","Client");accepted++;}catch(AgentRegistry.Failure e){assertEquals("RESOURCE_EXHAUSTED",e.code);break;}}assertEquals(8,accepted);registry.revokeAccess(request,1,UUID.randomUUID());registry.revokePeer(PEER,1,UUID.randomUUID());registry.decide(registry.review(app),"revoke",UUID.randomUUID());assertNull(registry.review(app).approved);}
    @Test public void invalidPendingRegistrationRollsBackAndOwnerNamespaceIsNotCallerInput(){String app=approveFixture();try{registry.register("@owner","spoof",UUID.randomUUID(),ManifestContract.parse(manifest("Spoof")));fail();}catch(IllegalArgumentException expected){assertEquals("Client",ManifestContract.parse(registry.review(app).pending.getBytes(StandardCharsets.UTF_8)).displayName);}}
    @Test public void relayPathIsExplicitDurableAndBoundToMethod() {
        String manifest=new String(manifest("Relay"),StandardCharsets.UTF_8).replace("direct-only","fast-connect").replace("\"allowRelay\":false","\"allowRelay\":true");
        String app=text(registry.register("caller","verified provenance",UUID.randomUUID(),ManifestContract.parse(manifest.getBytes(StandardCharsets.UTF_8))),"applicationRef");registry.decide(registry.review(app),"approve",UUID.randomUUID());registry.trustPeer(PEER,"public fixture certificate","127.0.0.1",17443,0,UUID.randomUUID());
        registry.approveAccess(request("caller",app),0,UUID.randomUUID());UUID operation=UUID.randomUUID(),boot=UUID.randomUUID();
        denied("CAPABILITY_UNSUPPORTED",()->registry.beginOpen("caller",operation,app,"files",PEER,"org.example.publisher","files",boot));
        AgentRegistry.Open opened=registry.beginRelayOpen("caller",operation,app,"files",PEER,"org.example.publisher","files",boot);assertEquals("relay",opened.path);assertTrue(opened.created);
        denied("OPERATION_CONFLICT",()->registry.beginOpen("caller",operation,app,"files",PEER,"org.example.publisher","files",boot));
        registry=new AgentRegistry(database,()->now);UUID next=UUID.randomUUID();registry.recoverOpens(next);AgentRegistry.Open retained=registry.beginRelayOpen("caller",operation,app,"files",PEER,"org.example.publisher","files",next);assertEquals("relay",retained.path);assertEquals("closed",retained.state);assertFalse(retained.created);assertEquals(opened.reference,retained.reference);
    }
    @Test public void relayCannotOverrideDirectOnlyAndOldOutcomesRemainDirect() {
        String app=approveFixture();registry.approveAccess(request("caller",app),0,UUID.randomUUID());UUID operation=UUID.randomUUID(),boot=UUID.randomUUID();
        denied("CAPABILITY_UNSUPPORTED",()->registry.beginRelayOpen("caller",operation,app,"files",PEER,"org.example.publisher","files",boot));
        AgentRegistry.Open opened=registry.beginOpen("caller",operation,app,"files",PEER,"org.example.publisher","files",boot);
        try(AgentRegistry.Session session=database.open()){session.begin();session.execute("UPDATE operations SET result=? WHERE caller=? AND operation=?","{\"connectionId\":\""+opened.reference+"\"}","caller",operation.toString());session.commit();}
        assertEquals("direct",registry.openStatus("caller",operation).path);
    }
    @Test public void unsupportedRelayLimitsCannotBecomeLocalAccess() {
        String declaration=new String(manifest("Budget"),StandardCharsets.UTF_8).replace("\"allowRelay\":false","\"allowRelay\":false,\"relayBudgetBytes\":\"100\",\"relayBudgetAction\":\"stop-relay\"");
        String app=text(registry.register("caller","provenance",UUID.randomUUID(),ManifestContract.parse(declaration.getBytes(StandardCharsets.UTF_8))),"applicationRef");registry.decide(registry.review(app),"approve",UUID.randomUUID());registry.trustPeer(PEER,"public fixture certificate","127.0.0.1",17443,0,UUID.randomUUID());denied("CAPABILITY_UNSUPPORTED",()->request("caller",app));
    }
    private dev.linkgate.contracts.ConnectionOpenRequest formalRequest(String app,String policy){return dev.linkgate.contracts.ConnectionOpenRequest.parse(WireJson.write(WireJson.map("applicationRef",app,"importAlias","files","deviceId",PEER,"publisherAppId","org.example.publisher","remoteServiceId","files","connectionPolicy",WireJson.read(policy.getBytes(StandardCharsets.UTF_8),8192)),16384));}
    private ConnectionMeter formalMeter(dev.linkgate.contracts.ConnectionStatus status,java.util.concurrent.atomic.AtomicLong nanos){return new ConnectionMeter(status.connectionId,status.ownerId,status.deviceId,status.publisherAppId,status.serviceId,status.bootId,status.networkGeneration,now,0,nanos::get);}
    @Test public void formalOpenRetainsActualOutcomeAndNeverRecreatesAfterRestart(){
        String app=approveFixture();registry.approveAccess(request("caller",app),0,UUID.randomUUID());var input=formalRequest(app,"{\"mode\":\"direct-only\",\"allowRelay\":false}");UUID op=UUID.randomUUID(),boot=UUID.randomUUID();var nanos=new java.util.concurrent.atomic.AtomicLong();var journal=registry.connections();var accepted=journal.begin("caller",op,input,boot,"1",now,0,nanos::get);assertTrue(accepted.created);assertEquals("pending",text(registry.operationStatus("caller",op),"status"));denied("OPERATION_UNKNOWN",()->journal.status("other",accepted.status.connectionId));
        ConnectionMeter meter=formalMeter(accepted.status,nanos);var stale=meter.snapshot();nanos.set(10000000);meter.ready("direct",10);journal.publish("caller",boot,meter.snapshot());assertEquals("succeeded",text(registry.operationStatus("caller",op),"status"));meter.attached();meter.bytes(true,5);meter.fin(true);assertTrue(journal.publish("caller",boot,meter.snapshot()));assertEquals("draining",journal.status("caller",accepted.status.connectionId).flowState);assertFalse(journal.publish("caller",boot,stale));UUID next=UUID.randomUUID();journal.recover(next,now+50);var restored=journal.status("caller",accepted.status.connectionId);assertEquals("GATEWAY_RESTARTED",restored.errorCode);assertEquals("5",restored.directTx.toString());assertFalse(restored.complete);assertEquals("succeeded",text(registry.operationStatus("caller",op),"status"));assertFalse(journal.begin("caller",op,input,next,"2",now+50,0,nanos::get).created);assertFalse(journal.publish("caller",boot,meter.snapshot()));
    }
    @Test public void formalPendingCrashIsFailedAndCloseDoesNotGrantAuthority(){
        String app=approveFixture();var input=formalRequest(app,"{\"mode\":\"direct-only\",\"allowRelay\":false}");UUID boot=UUID.randomUUID(),op=UUID.randomUUID();denied("AUTH_REQUIRED",()->registry.connections().begin("caller",op,input,boot,"1",now,0,()->0));registry.approveAccess(request("caller",app),0,UUID.randomUUID());var accepted=registry.connections().begin("caller",op,input,boot,"1",now,0,()->0);registry.connections().recover(UUID.randomUUID(),now+10);assertEquals("failed",text(registry.operationStatus("caller",op),"status"));UUID close=UUID.randomUUID();String result=registry.connections().prepareClose("caller",close,accepted.status.connectionId);assertEquals(result,registry.connections().prepareClose("caller",close,accepted.status.connectionId));denied("OPERATION_CONFLICT",()->registry.connections().prepareClose("caller",op,accepted.status.connectionId));
    }
    @Test public void formalAttachmentIsRetainedOneUseAndCurrentlyAuthorized(){
        String app=approveFixture(),grant=request("caller",app);registry.approveAccess(grant,0,UUID.randomUUID());UUID boot=UUID.randomUUID(),open=UUID.randomUUID(),attach=UUID.randomUUID();var input=formalRequest(app,"{\"mode\":\"direct-only\",\"allowRelay\":false}");var nanos=new java.util.concurrent.atomic.AtomicLong();var journal=registry.connections();var accepted=journal.begin("caller",open,input,boot,"1",now,0,nanos::get);denied("CONNECTION_NOT_READY",()->journal.attach("caller",attach,accepted.status.connectionId,boot));ConnectionMeter meter=formalMeter(accepted.status,nanos);meter.ready("direct",0);journal.publish("caller",boot,meter.snapshot());String result=journal.attach("caller",attach,accepted.status.connectionId,boot);assertEquals(result,journal.attach("caller",attach,accepted.status.connectionId,boot));var envelope=WireJson.read(result.getBytes(StandardCharsets.UTF_8),16384);String stream=(String)WireJson.object(envelope.get("result")).get("streamRef");denied("AUTH_REQUIRED",()->journal.consume("other",stream,boot));assertEquals(accepted.status.connectionId,journal.consume("caller",stream,boot));denied("AUTH_REQUIRED",()->journal.consume("caller",stream,boot));denied("STREAM_ALREADY_ATTACHED",()->journal.attach("caller",UUID.randomUUID(),accepted.status.connectionId,boot));
    }
    @Test public void formalRequestsCannotWidenApprovedPolicyOrConflictAnOperation(){
        String manifest=new String(manifest("Auto"),StandardCharsets.UTF_8).replace("direct-only","direct-first").replace("\"allowRelay\":false","\"allowRelay\":true");String app=text(registry.register("caller","verified",UUID.randomUUID(),ManifestContract.parse(manifest.getBytes(StandardCharsets.UTF_8))),"applicationRef");registry.decide(registry.review(app),"approve",UUID.randomUUID());registry.trustPeer(PEER,"public fixture certificate","127.0.0.1",17443,0,UUID.randomUUID());registry.approveAccess(request("caller",app),0,UUID.randomUUID());UUID op=UUID.randomUUID(),boot=UUID.randomUUID();var wider=formalRequest(app,"{\"mode\":\"fast-connect\"}");denied("PERMISSION_DENIED",()->registry.connections().begin("caller",op,wider,boot,"1",now,0,()->0));var valid=formalRequest(app,"{\"mode\":\"direct-first\"}");registry.connections().begin("caller",op,valid,boot,"1",now,0,()->0);var changed=formalRequest(app,"{\"mode\":\"direct-only\",\"allowRelay\":false}");denied("OPERATION_CONFLICT",()->registry.connections().begin("caller",op,changed,boot,"1",now,0,()->0));
    }
    @Test public void schemaOneMigrationPreservesExistingGrantsAndExperimentalOutcomes(){
        String app=approveFixture();registry.approveAccess(request("caller",app),0,UUID.randomUUID());UUID op=UUID.randomUUID(),boot=UUID.randomUUID();AgentRegistry.Open original=registry.beginOpen("caller",op,app,"files",PEER,"org.example.publisher","files",boot);try(var session=database.open()){session.begin();session.execute("DROP TABLE connection_attachments");session.execute("DROP TABLE connections");session.execute("DROP INDEX opens_active");session.execute("PRAGMA user_version=1");session.commit();}registry=new AgentRegistry(database,()->now);assertEquals(original.reference,registry.openStatus("caller",op).reference);assertNotNull(scope(app));
    }
    private static final class Jdbc implements AgentRegistry.Session {
        private final Connection connection;private boolean transaction;
        Jdbc(Connection connection)throws Exception {this.connection=connection;try(var statement=connection.createStatement()){statement.execute("PRAGMA busy_timeout=1000");statement.execute("PRAGMA synchronous=FULL");}}
        @Override public void begin(){try{connection.setAutoCommit(false);transaction=true;}catch(Exception e){throw new IllegalStateException();}}
        @Override public void execute(String sql,String... args){try(PreparedStatement statement=connection.prepareStatement(sql)){for(int i=0;i<args.length;i++)statement.setString(i+1,args[i]);statement.execute();}catch(Exception e){throw new IllegalStateException();}}
        @Override public List<String[]> query(String sql,String... args){try(PreparedStatement statement=connection.prepareStatement(sql)){for(int i=0;i<args.length;i++)statement.setString(i+1,args[i]);try(ResultSet result=statement.executeQuery()){List<String[]> rows=new ArrayList<>();while(result.next()){if(rows.size()>=64)throw new IllegalStateException();String[] row=new String[result.getMetaData().getColumnCount()];for(int i=0;i<row.length;i++)row[i]=result.getString(i+1);rows.add(row);}return rows;}}catch(Exception e){throw new IllegalStateException();}}
        @Override public void commit(){try{connection.commit();transaction=false;}catch(Exception e){throw new IllegalStateException();}}
        @Override public void close(){try{if(transaction)connection.rollback();connection.close();}catch(Exception e){throw new IllegalStateException();}}
    }
}
